/* -------------------------------------------------------------------------
   Empty

   Empty state placeholder. Centered layout with media, title,
   description, and action slot.

   Variants: outline (border), filled (bg)
   Parts:    .empty, .empty__header, .empty__media, .empty__title,
             .empty__description, .empty__content
   ------------------------------------------------------------------------- */

.empty {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 24px;
  width: 100%;
  padding: 48px 24px;
  font-family: 'inter tight', -apple-system, blinkmacsystemfont, 'segoe ui', roboto, helvetica, arial, sans-serif, ui-sans-serif, system-ui, sans-serif;
  text-align: center;
}

/* ---- Variants ---- */

.empty--outline {
  border: 1px dashed #e5e5e5;
  border-radius: 12px;
}

.empty--filled {
  background-color: #f5f5f5;
  border-radius: 12px;
}

/* ---- Header ---- */

.empty__header {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 12px;
  max-width: 420px;
}

/* ---- Media ---- */

.empty__media {
  display: flex;
  align-items: center;
  justify-content: center;
  color: #525252;
}

.empty__media--icon {
  width: 48px;
  height: 48px;
  border-radius: 12px;
  background-color: #f5f5f5;
  padding: 12px;
}

.empty--filled .empty__media--icon {
  background-color: #fafafa;
}

.empty__media svg {
  width: 100%;
  height: 100%;
}

/* ---- Title ---- */

.empty__title {
  font-size: 16px;
  font-weight: 600;
  line-height: 1.5;
  color: #0a0a0a;
  margin: 0;
}

/* ---- Description ---- */

.empty__description {
  font-size: 12.8px;
  line-height: 1.45;
  color: #525252;
  margin: 0;
}

/* ---- Content (actions slot) ---- */

.empty__content {
  display: flex;
  align-items: center;
  gap: 12px;
}
